using TownOfHost;using TownOfHost.Modules;using TownOfHost.Patches;using Hazel;using System.Reflection;
partial class Program {
 static int passed,failed;
 static void Check(bool b){if(!b)throw new Exception("assertion failed");}
 static void Reset(){LateTask.Tasks.Clear();CustomNetObject.AllObjects.Clear();CustomNetObject.ResetSpawnState();AmongUsClient.Instance=new(){GameState=AmongUsClient.GameStates.Started};AmongUsClient.Sends=0;AmongUsClient.ThrowSend=false;AmongUsClient.BeforeSend=null;AmongUsClient.Packets.Clear();MessageWriter.Created.Clear();MessageWriter.ThrowSerialize=false;PlayerControl.LocalPlayer=new();PlayerControl.AllPlayerControls.Clear();PlayerCatch.AllPlayerControls.Clear();GameStates.IsLobby=GameStates.IsEnded=false;Logger.Errors.Clear();DestroyableSingleton<EndGameNavigation>.InstanceExists=true;DestroyableSingleton<EndGameNavigation>.Value=new();DestroyableSingleton<EndGameNavigation>.Gets=0;typeof(AutoReturnToRoomPatch).GetField("ReturnScheduled",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,false);}
 static void Test(string name,Action run){Reset();if(name.Contains("automatic return"))AmongUsClient.Instance.GameState=AmongUsClient.GameStates.Ended;try{run();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
 class Dummy:CustomNetObject {public int Created;public Action WhenCreated;public void Spawn()=>CreateNetObject(new(1,2));public void Appearance()=>SetAppearance(1,displayName:"temporary");public void HideFrom(PlayerControl p)=>Hide(p);protected override void OnCreated(){Created++;WhenCreated?.Invoke();}}
 static CustomRpcSender Sender(){var s=CustomRpcSender.Create("synthetic");s.StartMessage();s.StartRpc(99,(byte)RpcCalls.SetName).Write("synthetic").EndRpc();return s;}
 static string PreloadBody([System.Runtime.CompilerServices.CallerFilePath]string file=""){var s=File.ReadAllText(Path.GetFullPath(Path.Combine(Path.GetDirectoryName(file),"../../Patches/ClientPatch.cs"))).Replace("\r\n","\n");int first=s.IndexOf("    [HarmonyPatch(typeof(AmongUsClient))]\n    class PreloadMapPatch");return s[first..s.LastIndexOf("\n}")];}
 static void Main(string[] args){if(args.Contains("--range-replay")){RangeReplay(args.Last());return;}if(args.Contains("--nova-traffic")){TrafficBench();return;}if(args.Contains("--bench")){Bench();return;}
 Test("cancelled due task never executes",()=>{int n=0;var t=new LateTask(()=>n++,.1f);t.CallStop();LateTask.Update(.2f);Check(n==0&&LateTask.Tasks.Count==0&&!t.Isruned);});
 Test("normal tasks retain same tick timing and order",()=>{var calls=new List<int>();new LateTask(()=>calls.Add(1),.1f);new LateTask(()=>calls.Add(2),.2f);LateTask.Update(.15f);Check(calls.SequenceEqual(new[]{1}));LateTask.Update(.1f);Check(calls.SequenceEqual(new[]{1,2}));});
 Test("task exception does not stop later tasks",()=>{int n=0;new LateTask(()=>throw new Exception(),.1f);new LateTask(()=>n++,.1f);LateTask.Update(.2f);Check(n==1&&LateTask.Tasks.Count==0);});
 Test("zero delay still executes immediately",()=>{int n=0;new LateTask(()=>n++,0);Check(n==1&&LateTask.Tasks.Count==0);});
 Test("task can cancel another due task before its turn",()=>{int n=0;LateTask target=null;new LateTask(()=>target.CallStop(),.1f);target=new LateTask(()=>n++,.1f);LateTask.Update(.2f);Check(n==0);});
 Test("sender normal wire sequence and send count retained",()=>{var s=Sender();s.SendMessage();Check(AmongUsClient.Sends==1&&s.stream.Recycles==1&&s.CurrentState==CustomRpcSender.State.Finished);Check(AmongUsClient.Packets.Single().SequenceEqual(new[]{"start:5","write:Int32:7","start:2","packed:99","write:Byte:6","write:String:synthetic","end","end"}));});
 Test("sender returns writer after transport exception",()=>{var s=Sender();AmongUsClient.ThrowSend=true;try{s.SendMessage();}catch(InvalidOperationException){}Check(s.stream.Recycles==1&&s.CurrentState==CustomRpcSender.State.Finished);});
 Test("sender callback failure cannot replay delivered packet",()=>{var s=Sender();s.onSendDelegate=()=>throw new Exception();try{s.SendMessage();}catch{}try{s.SendMessage();}catch{}Check(AmongUsClient.Sends==1&&s.stream.Recycles==1);});
 Test("sender second normal send is rejected without second recycle",()=>{var s=Sender();s.SendMessage();try{s.SendMessage();}catch(InvalidOperationException){}Check(AmongUsClient.Sends==1&&s.stream.Recycles==1);});
 Test("appearance restores host outfit when serialization throws",()=>{var d=new Dummy{PlayerControl=new()};MessageWriter.ThrowSerialize=true;try{d.Appearance();}catch{}var o=PlayerControl.LocalPlayer.Data.Outfits[PlayerOutfitType.Default];Check(o.PlayerName=="original"&&o.ColorId==7&&o.HatId=="hat");Check(MessageWriter.Created.All(w=>w.Recycles==1));});
 Test("appearance normal payload still restores host outfit",()=>{var d=new Dummy{PlayerControl=new()};d.Appearance();Check(AmongUsClient.Sends==1&&PlayerControl.LocalPlayer.Data.Outfits[PlayerOutfitType.Default].PlayerName=="original");var p=AmongUsClient.Packets.Single();Check(p.Contains("outfit:temporary")&&p.Contains("outfit:original"));});
 Test("old spawn callback cannot unlock the next game queue",()=>{var old=new Dummy();old.Spawn();var previous=LateTask.Tasks.ToArray();CustomNetObject.Reset();LateTask.Tasks.Clear();var current=new Dummy();current.Spawn();var waiting=new Dummy();waiting.Spawn();int before=AmongUsClient.Sends;foreach(var t in previous)t.Run(1);Check(AmongUsClient.Sends==before&&waiting.PlayerControl==null&&current.Created==0);});
 Test("normal spawn completes and releases queued spawn",()=>{var a=new Dummy();a.Spawn();var b=new Dummy();b.Spawn();Check(b.PlayerControl==null);LateTask.Update(.4f);Check(a.Created==1&&b.PlayerControl!=null);});
 Test("despawn returns writer after transport exception",()=>{var d=new Dummy{PlayerControl=new()};CustomNetObject.AllObjects.Add(d);AmongUsClient.ThrowSend=true;d.Despawn();Check(MessageWriter.Created.Single().Recycles==1);});
 Test("despawn after client teardown does not throw",()=>{var d=new Dummy{PlayerControl=new()};AmongUsClient.Instance=null;d.Despawn();});
 Test("normal automatic return keeps five second timing",()=>{AutoReturnToRoomPatch.Postfix(new());LateTask.Update(4);Check(DestroyableSingleton<EndGameNavigation>.Value.Calls==0);LateTask.Update(1);Check(DestroyableSingleton<EndGameNavigation>.Value.Calls==1);});
 Test("automatic return ignores destroyed results screen",()=>{var end=new EndGameManager();AutoReturnToRoomPatch.Postfix(end);end.Destroyed=true;LateTask.Update(5);Check(DestroyableSingleton<EndGameNavigation>.Value.Calls==0);});
 Test("automatic return ignores changed game session",()=>{AutoReturnToRoomPatch.Postfix(new());AmongUsClient.Instance.GameId++;LateTask.Update(5);Check(DestroyableSingleton<EndGameNavigation>.Value.Calls==0);});
 Test("automatic return never creates missing navigation singleton",()=>{AutoReturnToRoomPatch.Postfix(new());DestroyableSingleton<EndGameNavigation>.InstanceExists=false;LateTask.Update(5);Check(DestroyableSingleton<EndGameNavigation>.Gets==0);});
 Test("automatic return skips an inactive results object",()=>{var end=new EndGameManager();AutoReturnToRoomPatch.Postfix(end);end.gameObject.SetActive(false);LateTask.Update(5);Check(DestroyableSingleton<EndGameNavigation>.Value.Calls==0);});
 Test("automatic return deduplicates ShowButtons for the same screen",()=>{var end=new EndGameManager();AutoReturnToRoomPatch.Postfix(end);AutoReturnToRoomPatch.Postfix(end);Check(LateTask.Tasks.Count==1);LateTask.Update(5);Check(DestroyableSingleton<EndGameNavigation>.Value.Calls==1);});
 Test("automatic return supersedes an old results timer safely",()=>{AutoReturnToRoomPatch.Postfix(new());LateTask.Update(2);AutoReturnToRoomPatch.Postfix(new());LateTask.Update(3);Check(DestroyableSingleton<EndGameNavigation>.Value.Calls==0);LateTask.Update(2);Check(DestroyableSingleton<EndGameNavigation>.Value.Calls==1);});
 Test("automatic return tolerates client destruction",()=>{AutoReturnToRoomPatch.Postfix(new());AmongUsClient.Instance=null;LateTask.Update(5);Check(DestroyableSingleton<EndGameNavigation>.Value.Calls==0&&Logger.Errors.Count==0);});
 Test("sender unsent dispose is idempotent",()=>{var s=Sender();((IDisposable)s).Dispose();((IDisposable)s).Dispose();Check(s.stream.Recycles==1&&AmongUsClient.Sends==0);});
 Test("appearance restores all borrowed fields after send failure",()=>{var d=new Dummy{PlayerControl=new()};AmongUsClient.ThrowSend=true;try{d.Appearance();}catch{}var o=PlayerControl.LocalPlayer.Data.Outfits[PlayerOutfitType.Default];Check(o.PlayerName=="original"&&o.ColorId==7&&o.HatId=="hat"&&o.SkinId=="skin"&&o.PetId=="pet"&&o.VisorId=="visor");Check(MessageWriter.Created.Single().Recycles==1);});
 Test("CNO spawn refuses disconnected client state without any packet",()=>{AmongUsClient.Instance.GameState=AmongUsClient.GameStates.NotJoined;var d=new Dummy();d.Spawn();Check(d.PlayerControl==null&&AmongUsClient.Sends==0&&LateTask.Tasks.Count==0);});
 Test("pending CNO callbacks cannot send after disconnect",()=>{var d=new Dummy();d.Spawn();var tasks=LateTask.Tasks.ToArray();int sent=AmongUsClient.Sends;AmongUsClient.Instance.GameState=AmongUsClient.GameStates.NotJoined;foreach(var t in tasks)t.Run(1);Check(sent==AmongUsClient.Sends&&d.Created==0);});
 Test("pending CNO callbacks cannot send to a replacement client",()=>{var d=new Dummy();d.Spawn();var tasks=LateTask.Tasks.ToArray();int sent=AmongUsClient.Sends;AmongUsClient.Instance=new(){GameState=AmongUsClient.GameStates.Started};foreach(var t in tasks)t.Run(1);Check(sent==AmongUsClient.Sends&&d.Created==0);});
 Test("CNO spawn failure returns its explicitly allocated writer",()=>{AmongUsClient.ThrowSend=true;new Dummy().Spawn();Check(MessageWriter.Created.Single().Recycles==1);});
 Test("CNO remote hide failure returns its writer",()=>{var d=new Dummy{PlayerControl=new()};AmongUsClient.ThrowSend=true;try{d.HideFrom(new PlayerControl());}catch{}Check(MessageWriter.Created.Single().Recycles==1);});
 Test("stopped scheduler task still removes without advancing other deadlines",()=>{int n=0;var stopped=new LateTask(()=>n+=100,.1f);stopped.CallStop();new LateTask(()=>n++,.5f);LateTask.Update(.1f);Check(n==0&&LateTask.Tasks.Count==1);LateTask.Update(.4f);Check(n==1);});
 Test("spawn binding skips disconnected and incomplete peers",()=>{PlayerCatch.AllPlayerControls.Add(null);PlayerCatch.AllPlayerControls.Add(new(){Data=null});PlayerCatch.AllPlayerControls.Add(new(){Data=new(){Disconnected=true}});PlayerCatch.AllPlayerControls.Add(new(){PlayerId=3});var d=new Dummy();d.Spawn();int n=AmongUsClient.Sends;LateTask.Update(.1f);Check(AmongUsClient.Sends==n+1&&Logger.Errors.Count==0);});
 Test("spawn binding tolerates vanished local host data",()=>{var d=new Dummy();d.Spawn();PlayerControl.LocalPlayer=null;LateTask.Update(.1f);Check(Logger.Errors.Count==0);});
