 Test("map unload never reads a released handle result",()=>{var lease=new UnityEngine.ResourceManagement.AsyncOperations.Lease{Valid=false};PreloadMapPatch.handles.Clear();PreloadMapPatch.handles.Add(new(){Lease=lease});PreloadMapPatch.lastToggle=true;TownOfHost.Main.PreloadMapAssets.Value=false;PreloadMapPatch.Preload();Check(lease.ResultReads==0&&lease.Releases==0&&PreloadMapPatch.handles.Count==0);});
