 Test("map unload releases completed handle exactly once",()=>{var lease=new UnityEngine.ResourceManagement.AsyncOperations.Lease();PreloadMapPatch.handles.Clear();PreloadMapPatch.handles.Add(new(){Lease=lease});PreloadMapPatch.lastToggle=true;TownOfHost.Main.PreloadMapAssets.Value=false;PreloadMapPatch.Preload();PreloadMapPatch.Preload();Check(lease.Releases==1&&PreloadMapPatch.handles.Count==0);});
