 static void Bench(){Reset();for(int n=0;n<10000;n++)LateTask.Update(.02f);long bytes=GC.GetAllocatedBytesForCurrentThread(),time=System.Diagnostics.Stopwatch.GetTimestamp();for(int n=0;n<100000;n++)LateTask.Update(.02f);var elapsed=TimeSpan.FromSeconds((double)(System.Diagnostics.Stopwatch.GetTimestamp()-time)/System.Diagnostics.Stopwatch.Frequency);Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{iterations=100000,allocated_bytes=GC.GetAllocatedBytesForCurrentThread()-bytes,milliseconds=elapsed.TotalMilliseconds}));}
